from taf.ul.sc.uesim.generic_controller import GenericController
from moler.util.moler_test import MolerTest


class Controller(GenericController):
    def __init__(self,
                 device_name='CUS_CTRL1',    # type: 'Optional[str]'
                 device=None,                # type: 'Optional[RtgController]'
                 autoconnect=True,           # type: 'Optional[bool]'
                 get_device=False            # type: 'Optional[bool]'
                 ):

        super(Controller, self).__init__(device_name=device_name, device=device,
                                         autoconnect=autoconnect, get_device=get_device)
        self.basic_state = "FCT"

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def run_dsp_command(self, dsp_number, dsp_command, fsp_number="1a", timeout=10):
        self.connect_dsp(dsp_number, fsp_number=fsp_number)
        dsp_command = self.device.get_cmd(cmd_name="run_dsp_command", cmd_params={"dsp_command": dsp_command})
        result = dsp_command(timeout)
        self.connect_fct()
        MolerTest.steps_end()
        return result['LINES']

    def connect_fct(self, timeout=300):
        self.device.goto_state("FCT", timeout=timeout, rerun=1000)

    def connect_dsp(self, dsp_number, fsp_number="1a", timeout=20, rerun=1):
        dsp = "{}-dsp{}".format(fsp_number, dsp_number)
        self.device.goto_state(dsp, timeout=timeout, rerun=rerun)

    def reboot_controller(self, timeout=600):
        """
        Reboot Controller.

        :return: None
        """
        self.device.goto_state(self.basic_state)

        enter_cmd = self.device.get_cmd(cmd_name="enter")
        enter_cmd()

        sync_cmd = self.device.get_cmd(cmd_name="sync")
        sync_cmd()

        reboot_cmd = self.device.get_cmd(cmd_name="reboot")
        reboot_cmd(timeout=timeout)
        MolerTest.sleep(60)
        self.device.goto_state("FCT", timeout=timeout, rerun=1000)
        MolerTest.sleep(60)
        MolerTest.steps_end()
